      (lot.method === 'silent' ? !Object.hasOwn(lot.sealed, player.id) : lot.active === player.id)
      ? [{ type: 'richeseBid', event: lot.event, amount: lot.method === 'silent' ? 0 : null, allyPayment: 0 }] : [];
