  requireRule(
    plan.leader ||
      (!available.length &&
        (!p.hand.some((c) => c.kind === 'hero') ||
          (b.voice?.target === p.id &&
            !b.voice.must &&
            b.voice.kind === 'hero'))),
    'You must use an available leader or cheap hero.',
  );
  const w = cardOf(p, plan.weapon),
    d = cardOf(p, plan.defense);
