    requireRule(
      g.advanced && p.faction === 'atreides' && p.kwisatz?.dead,
      'Kwisatz Haderach is not in the tanks.',
    );
  else
    requireRule(
      l?.dead && !l.capturedBy && !l.gholaBy,
      'Choose a dead leader.',
    );
