  if ((!revivalQuestionWindow(g) && !ownPayment) || g.truthtrance || !revivalOpportunity(g, player) ||
    g.pendingRevival || g.pendingKarama || g.pendingTreacheryDiscard ||
    g.phase === 4 && nativeRevivalOrderBlock(g, player)) return null;
